use crate::files::{args,bytes,path,text,MAX_FILE};
use serde_json::{json,Value};
use std::{fs,path::{Path,PathBuf}};
pub fn number(v:&Value,k:&str,default:usize,max:usize)->Result<usize,String>{match v.get(k){None=>Ok(default),Some(x)=>{let n=x.as_u64().ok_or_else(||format!("{k} must be a non-negative integer"))?;if n>max as u64{return Err(format!("{k} exceeds maximum {max}"));}Ok(n as usize)}}}
pub fn boolean(v:&Value,k:&str)->Result<bool,String>{match v.get(k){None=>Ok(false),Some(x)=>x.as_bool().ok_or_else(||format!("{k} must be boolean"))}}
pub fn read_string(p:&Path)->Result<String,String>{let b=bytes(p)?;if b.contains(&0){return Err("Binary/document extraction unavailable; use file_get".into());}String::from_utf8(b).map_err(|_|"Not UTF-8 text; binary/document extraction unavailable".into())}
pub fn text_tool(name:&str,v:&Value)->Result<Value,String>{match name{
 "write_file"=>{args(v,&["path","content"])?;let p=path(text(v,"path")?)?;let s=text(v,"content")?;crate::files::replace(&p,s)?;Ok(json!({"path":p,"bytes_written":s.len(),"verified":true}))},
 "patch"=>{args(v,&["path","old_string","new_string","replace_all"])?;let p=path(text(v,"path")?)?;let old=text(v,"old_string")?;let new=text(v,"new_string")?;if old.is_empty()||old==new{return Err("old_string must be nonempty and differ from new_string".into());}let s=read_string(&p)?;let count=s.matches(old).count();if count==0||count>1&&!boolean(v,"replace_all")?{return Err(format!("Expected unique match; found {count}. Use replace_all for multiple matches"));}let result=s.replace(old,new);crate::files::replace(&p,&result)?;Ok(json!({"success":true,"replacements":count,"path":p}))},
 "search_files"=>search(v),_=>tool(name,v)}}
fn prefix_bytes(s:&str,max:usize)->&str{if s.len()<=max{return s;}let mut end=max;while end>0&&!s.is_char_boundary(end){end-=1;}&s[..end]}
fn read_file(v:&Value)->Result<Value,String>{const BUDGET:usize=100_000;args(v,&["path","offset","limit"])?;let p=path(text(v,"path")?)?;let s=read_string(&p)?;let offset=number(v,"offset",1,usize::MAX)?;if offset==0{return Err("offset is 1-indexed".into());}let limit=number(v,"limit",2000,2000)?;let lines:Vec<_>=s.lines().collect();let mut content=String::new();let mut next=offset;let mut cut=false;for (i,l) in lines.iter().enumerate().skip(offset-1).take(limit){let line=format!("{}|{}",i+1,l);let extra=line.len()+if content.is_empty(){0}else{1};if content.len()+extra>BUDGET{if content.is_empty(){content.push_str(prefix_bytes(&line,BUDGET));cut=true;next=i+2;}break;}if !content.is_empty(){content.push('\n');}content.push_str(&line);next=i+2;}Ok(json!({"content":content,"total_lines":lines.len(),"file_size":s.len(),"truncated":cut||next<=lines.len(),"next_offset":next,"is_binary":false,"is_image":false,"not_found":false}))}
pub fn tool(name:&str,v:&Value)->Result<Value,String>{match name{
 "read_file"=>read_file(v),
 "write_file"|"patch"|"search_files"=>text_tool(name,v),_=>Err(format!("Unknown text tool: {name}"))}}
fn walk(p:&Path,out:&mut Vec<PathBuf>,budget:&mut usize)->Result<(),String>{if *budget==0{return Err("Search exceeds 100000-entry traversal limit; narrow path".into());}*budget-=1;let meta=fs::symlink_metadata(p).map_err(|e|e.to_string())?;if meta.file_type().is_symlink(){return Ok(());}if meta.is_file(){out.push(p.into());}else if meta.is_dir(){let mut entries:Vec<_>=fs::read_dir(p).map_err(|e|e.to_string())?.collect::<Result<_,_>>().map_err(|e|e.to_string())?;entries.sort_by_key(|e|e.file_name());for e in entries{walk(&e.path(),out,budget)?;}}Ok(())}
pub fn all_files(p:&Path)->Result<Vec<PathBuf>,String>{let mut out=Vec::new();walk(p,&mut out,&mut 100000)?;Ok(out)}
fn glob(pattern:&str)->Result<regex::Regex,String>{let mut s=String::from("^");for c in pattern.chars(){match c{'*'=>s.push_str(".*"),'?'=>s.push('.'),_=>s.push_str(&regex::escape(&c.to_string()))}}s.push('$');regex::Regex::new(&s).map_err(|e|e.to_string())}
fn search(v:&Value)->Result<Value,String>{args(v,&["pattern","target","path","file_glob","limit","offset","order","output_mode","context"])?;let pat=text(v,"pattern")?;let target=v.get("target").and_then(Value::as_str).unwrap_or("content");if target!="files"&&target!="content"{return Err("target must be files or content".into());}if let Some(order)=v.get("order").filter(|x|!x.is_null()){if order!="discovery"{return Err("Only discovery order is supported".into());}}
 let mode=v.get("output_mode").and_then(Value::as_str).unwrap_or("content");if !["content","files_only","count"].contains(&mode){return Err("Unsupported output_mode".into());}let context=number(v,"context",0,50)?;let limit=number(v,"limit",50,1000)?;let offset=number(v,"offset",0,100000)?;let p=path(v.get("path").and_then(Value::as_str).unwrap_or("."))?;let files=all_files(&p)?;let filter=v.get("file_glob").and_then(Value::as_str).map(glob).transpose()?;let re=if target=="files"{glob(pat)?}else{regex::Regex::new(pat).map_err(|e|e.to_string())?};let mut matches=Vec::new();let mut skipped=Vec::new();let mut budget=0;
 for p in files{if let Some(g)=&filter{if !g.is_match(&p.file_name().unwrap_or_default().to_string_lossy()){continue;}}if target=="files"{if re.is_match(&p.file_name().unwrap_or_default().to_string_lossy()){matches.push(json!(p));}continue;}
 let s=match read_string(&p){Ok(s)=>s,Err(e)=>{skipped.push(json!({"path":p,"error":e}));continue;}};budget+=s.len();if budget>64*MAX_FILE{return Err("Search exceeds 512 MiB scan budget; narrow path".into());}let lines:Vec<_>=s.lines().collect();let hits:Vec<_>=lines.iter().enumerate().filter(|(_,l)|re.is_match(l)).collect();if mode=="files_only"{if !hits.is_empty(){matches.push(json!(p));}}else if mode=="count"{if !hits.is_empty(){matches.push(json!({"path":p,"count":hits.len()}));}}else{for(i,l)in hits{matches.push(json!({"path":p,"line":i+1,"content":l,"context_before":lines[i.saturating_sub(context)..i],"context_after":lines[i+1..std::cmp::min(i+1+context,lines.len())]}));}}if matches.len()>100000{return Err("Search exceeds match budget; narrow pattern".into());}}
 let count=matches.len();let selected:Vec<_>=matches.into_iter().skip(offset).take(limit).collect();if target=="files"{Ok(json!({"files":selected,"total_count":count}))}else{Ok(json!({"matches":selected,"total_count":count,"skipped":skipped.into_iter().take(100).collect::<Vec<_>>()}))}}
